import re

# Extract policy names and their associated evidence
policies = {}
for idx, row in df.iterrows():
    evidence = row['evidence']
    # Look for policy names (words ending with 'Policy')
    policy_matches = re.findall(r'(\w+Policy)', evidence)
    for policy in policy_matches:
        if policy not in policies:
            policies[policy] = []
        policies[policy].append({
            'doc_id': row['doc_id'],
            'evidence': evidence,
            'source': row['source']
        })

print('Policies found:')
for policy, records in policies.items():
    print(f"\n{policy}:")
